import Fluent
import Vapor

/// A swipe of a room event made by a member. `happeningId` is generated by the client which makes sending idempotent.
final class RoomHappening: Model, @unchecked Sendable {
    static let schema = "room_happenings"

    @ID(key: .id) var id: UUID?
    @Parent(key: "room_id") var room: Room
    @Parent(key: "user_id") var user: User
    @Field(key: "happening_id") var happeningId: UUID
    @Field(key: "date_created") var dateCreated: Date

    init() {}

    init(roomId: UUID, userId: UUID, happeningId: UUID, dateCreated: Date) {
        self.$room.id = roomId
        self.$user.id = userId
        self.happeningId = happeningId
        self.dateCreated = dateCreated
    }
}

struct CreateRoomHappening: AsyncMigration {
    func prepare(on database: any Database) async throws {
        try await database.schema(RoomHappening.schema)
            .id()
            .field("room_id", .uuid, .required, .references(Room.schema, "id", onDelete: .cascade))
            .field("user_id", .uuid, .required, .references(User.schema, "id", onDelete: .cascade))
            .field("happening_id", .uuid, .required)
            .field("date_created", .datetime, .required)
            .unique(on: "room_id", "user_id", "happening_id")
            .create()
    }

    func revert(on database: any Database) async throws {
        try await database.schema(RoomHappening.schema).delete()
    }
}
